// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }
    function testFuzz_property(uint256 valA, uint256 valB) public {
        c.SetMinSum(valA);
        c.Initialized();
        bool ok = true;
        try c.SetMinSum(valB) { ok = true; } catch { ok = false; }
        assertTrue(!ok || c.MinSum() == valA);
    }
}
